JSON;

    public function __construct(private readonly BigFivePrivateResultPackLoader $loader) {}

    /** @return array<string,mixed>|null */
    public function project(array $report): ?array
    {
        if (! in_array($report['scale_code'] ?? null, ['BIG5_OCEAN', 'BIG_FIVE_OCEAN_MODEL'], true)) {
            return null;
        }
        if (! is_array($report['sections'] ?? null)) {
            return $this->unavailable('sections_missing_or_invalid');
        }
        $originalAuthority = data_get($report, '_meta.big5_private_result_authority');
        $engine = data_get($report, '_meta.big5_report_engine_v2');
        $locales = array_values(array_unique(array_filter([
            data_get($originalAuthority, 'locale'), data_get($engine, 'locale'), $report['locale'] ?? null,
        ], static fn ($value): bool => is_string($value) && $value !== '')));
        $locale = $locales[0] ?? null;
        if (count($locales) !== 1 || ! in_array($locale, ['en', 'zh-CN'], true)) {
            return $this->unavailable('locale_invalid_or_conflicting');
        }
        $loaded = $this->loader->load($locale);
        $mapping = [];
        foreach (json_decode(self::FINGERPRINTS, true, 64, JSON_THROW_ON_ERROR) as $row) {
            if ($row['locale'] !== $locale) {
                continue;
            }
            $value = $this->registryValue($loaded['registry'], $row);
            if (! is_string($value) || ! hash_equals($row['after_sha256'], hash('sha256', $value))) {
                throw new RuntimeException('BIG5_READING_COPY_ACTIVE_LEAF_DRIFT');
            }
            $row['after'] = $value;
            if ($row['registry_path'][0] === 'action_rules') {
                $rules = $loaded['registry']['action_rules'][$row['registry_path'][1]]['rules'];
                $target = $row['selector']['identity_value'] ?? null;
                $selected = $target !== null ? array_values(array_filter($rules, static fn ($rule): bool => $rule['rule_id'] === $target)) : [];
                $row['action_bucket'] = $target !== null ? ($selected[0]['bucket'] ?? null) : $row['registry_path'][3];
                $row['action_rule_ids'] = array_column(array_values(array_filter($rules, static fn ($rule): bool => $rule['bucket'] === $row['action_bucket'])), 'rule_id');
            }
            $mapping[$row['before']] = $row;
        }
        $applied = [];
        $projected = $report;
        $projected['sections'] = $this->sections($report['sections'], $mapping, $applied);
        foreach (['big5_report_engine_v2', 'big5_public_projection_v1'] as $key) {
            $source = data_get($report, '_meta.'.$key);
            if (! is_array($source)) {
                continue;
            }
            if (is_array($source['sections'] ?? null)) {
                $source['sections'] = $this->sections($source['sections'], $mapping, $applied);
            }
            $source = $this->selectedCopies($source, $mapping, $applied);
            data_set($projected, '_meta.'.$key, $source);
        }
        $projected = $this->selectedCopies($projected, $mapping, $applied);
        foreach ([$projected, (array) data_get($projected, '_meta.big5_report_engine_v2'),
            (array) data_get($projected, '_meta.big5_public_projection_v1')] as $container) {
            foreach (['sections', 'facet_deviations', 'composite_insights', 'action_matrix'] as $key) {
                if ($this->containsBefore($container[$key] ?? null, $mapping)) {
                    return $this->unavailable('unmatched_copy_identity');
                }
            }
        }
        if ($applied === []) {
            return null;
        }

        return [
            'status' => 'ready',
            'schema_version' => 'big5.reading_copy.v1',
            'revision' => self::REVISION,
            'locale' => $locale,
            'original_authority' => $originalAuthority,
            'reading_authority' => $loaded['authority'],
            // These identify decoded report projections, not original DB JSON bytes.
            'original_report_sha256' => $this->digest($report),
            'projected_report_sha256' => $this->digest($projected),
            'applied_keys' => array_values(array_unique($applied)),
            'report' => $projected,
        ];
    }

    private function registryValue(array $registry, array $row): mixed
    {
        if ($row['selector'] === null) {
            return $this->at($registry, $row['registry_path']);
        }
        $selector = $row['selector'];
        $matches = array_values(array_filter((array) $this->at($registry, $selector['array_path']),
            static fn ($entry): bool => is_array($entry) && ($entry[$selector['identity_key']] ?? null) === $selector['identity_value']));
        if (count($matches) !== 1) {
            throw new RuntimeException('BIG5_READING_COPY_ACTIVE_IDENTITY_DRIFT');
        }

        return $this->at($matches[0], $selector['tail']);
    }

    private function at(mixed $value, array $path): mixed
    {
        foreach ($path as $key) {
            if (! is_array($value) || ! array_key_exists($key, $value)) {
                return null;
            }
            $value = $value[$key];
        }

        return $value;
    }

    private function sections(array $sections, array $mapping, array &$applied): array
    {
        foreach ($sections as &$section) {
            if (! is_array($section) || ! is_array($section['blocks'] ?? null)) {
                continue;
            }
            $sectionKey = $section['section_key'] ?? $section['key'] ?? '';
            $comparisonAllowed = false;
            if ($sectionKey === 'norms_comparison') {
                foreach ($section['blocks'] as $block) {
                    if (($block['block_uid'] ?? null) === 'norms_comparison.evidence'
                        && ($block['block_id'] ?? null) === 'norm_evidence_v1'
                        && ($block['component'] ?? null) === 'BigFiveNormEvidenceCard') {
                        $comparisonAllowed = data_get($block, 'resolved_copy.comparison_allowed') === true;
                    }
                }
            }
            $blocks = [];
            foreach ($section['blocks'] as $block) {
                if (! is_array($block)) {
                    $blocks[] = $block;

                    continue;
                }
                $trait = data_get($block, 'analytics.trait_code');
                $band = data_get($block, 'analytics.band');
                if ($sectionKey === 'norms_comparison' && ! $comparisonAllowed
                    && in_array($trait, ['O', 'C', 'E', 'A', 'N'], true) && in_array($band, ['low', 'mid', 'high'], true)
                    && ($block['kind'] ?? null) === 'trait_atomic' && ($block['component'] ?? null) === 'BigFiveTraitBlock'
                    && ($block['block_uid'] ?? null) === "norms_comparison.atomic.$trait.$band"
                    && ($block['block_id'] ?? null) === "atomic_{$trait}_{$band}"
                    && in_array("atomic/$trait.json#bands.$band.slots.norms_comparison", (array) data_get($block, 'provenance.atomic_refs'), true)) {
                    $applied[] = 'norms_comparison.without_comparison.'.$trait.'.'.$band;

                    continue;
                }
                if (is_array($block['resolved_copy'] ?? null)) {
                    $block['resolved_copy'] = $this->copyTree($block['resolved_copy'], $mapping, $applied, $block);
                }
                $blocks[] = $block;
            }
            $section['blocks'] = $blocks;
        }
        unset($section);

        return $sections;
    }

    private function selectedCopies(array $payload, array $mapping, array &$applied): array
    {
        foreach (['facet_deviations', 'composite_insights', 'action_matrix'] as $key) {
            if (is_array($payload[$key] ?? null)) {
                $payload[$key] = $this->copyTree($payload[$key], $mapping, $applied, ['_copy_container' => $key]);
            }
        }

        return $payload;
    }

    private function copyTree(mixed $value, array $mapping, array &$applied, array $identity): mixed
    {
        if (is_array($value)) {
            if (isset($value['scenario_key'])) {
                $identity['_copy_parent_scenario'] = $value['scenario_key'];
            }
            if (isset($value['rule_id'])) {
                // Renderer items omit scenario. Preserve the validated parent provenance/analytics.
                foreach (['rule_id', 'domain_code', 'bucket', 'scenario'] as $key) {
                    if (array_key_exists($key, $value)) {
                        $identity[$key] = $value[$key];
                    }
                }
            }
            foreach ($value as $key => $child) {
                $value[$key] = $this->copyTree($child, $mapping, $applied, $identity);
            }

            return $value;
        }
        if (! is_string($value) || ! isset($mapping[$value]) || ! $this->matchesIdentity($identity, $mapping[$value])) {
            return $value;
        }
        $row = $mapping[$value];
        $applied[] = implode('.', $row['registry_path']);

        return $row['after'];
    }

    private function matchesIdentity(array $identity, array $row): bool
    {
        [$family, $name] = $row['registry_path'];
        $refs = [];
        foreach ((array) ($identity['provenance'] ?? []) as $values) {
            $refs = array_merge($refs, (array) $values);
        }
        if ($family === 'atomic') {
            $path = $row['registry_path'];
            $band = $path[3];
            $section = $path[5];

            return ($identity['block_uid'] ?? null) === "$section.atomic.$name.$band"
                && data_get($identity, 'analytics.trait_code') === $name
                && data_get($identity, 'analytics.band') === $band
                && in_array("atomic/$name.json#bands.$band.slots.$section", $refs, true);
        }
        if ($family === 'facet_glossary') {
            $id = $row['selector']['identity_value'];

            return data_get($identity, 'analytics.facet_code') === $id
                && in_array("facet_glossary/$name.json#facets.$id", $refs, true);
        }
        if ($family === 'facet_precision') {
            $id = $row['selector']['identity_value'];

            return in_array("facet_precision/$name.json#rules.$id", $refs, true)
                || (($identity['rule_id'] ?? null) === $id && ($identity['domain_code'] ?? null) === $name);
        }
        if ($family === 'synergies') {
            return (data_get($identity, 'analytics.synergy_id') === $name && in_array("synergies/$name.json", $refs, true))
                || ($identity['rule_id'] ?? null) === $name;
        }
        if ($family === 'action_rules') {
            $ruleId = $identity['rule_id'] ?? null;
            $parentScenario = $identity['_copy_parent_scenario'] ?? data_get($identity, 'analytics.scenario_key') ?? data_get($identity, 'analytics.top_priority_scenario');
            $scenario = $identity['scenario'] ?? $parentScenario;
            $bound = $scenario === $name && ($parentScenario === null || $parentScenario === $name)
                && (in_array("action_rules/$name.json", $refs, true) || ($identity['_copy_container'] ?? null) === 'action_matrix');
            if (! $bound || ($identity['bucket'] ?? null) !== $row['action_bucket']
                || ! in_array($ruleId, $row['action_rule_ids'], true)) {
                return false;
            }

            return $row['selector'] === null || $ruleId === $row['selector']['identity_value'];
        }

        return $family === 'shared' && $name === 'runtime_copy'
            && ($identity['block_uid'] ?? null) === match ($row['registry_path'][3]) {
                'intro' => 'facet_details.precision_intro',
                'overflow' => 'facet_details.anomaly_overflow',
                default => null,
            };
    }

    private function unavailable(string $reason): array
    {
        return ['schema_version' => 'big5.reading_copy.v1', 'revision' => self::REVISION,
            'status' => 'unavailable', 'reason' => $reason];
    }

    private function containsBefore(mixed $value, array $mapping): bool
    {
        if (is_string($value)) {
            return isset($mapping[$value]);
        }
        foreach (is_array($value) ? $value : [] as $child) {
            if ($this->containsBefore($child, $mapping)) {
                return true;
            }
        }

        return false;
    }

    private function digest(array $value): string
    {
        $normalize = function (mixed $item) use (&$normalize): mixed {
            if (! is_array($item)) {
                return $item;
            }
            if (! array_is_list($item)) {
                ksort($item, SORT_STRING);
            }
            foreach ($item as $key => $child) {
                $item[$key] = $normalize($child);
            }

            return $item;
        };

        return hash('sha256', json_encode($normalize($value), JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION));
    }
}
